import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';

import 'support/cli_kernel.dart';
import 'support/test_process.dart';

/// `dartway format` formats what the branch changed, with the Dart of the
/// Flutter the project pins, and never a generated file or a migration.
void main() {
  var repository = Directory.current.absolute;
  while (!Directory(p.join(repository.path, 'toolkit')).existsSync()) {
    repository = repository.parent;
  }
  final packages = p.join(repository.path, '.dart_tool/package_config.json');
  late String cli;
  setUpAll(() async => cli = await cliKernel(repository.path));

  late Directory temp;
  late Directory root;
  late File sdkLog;
  setUp(() {
    temp = Directory.systemTemp.createTempSync('dw_format_');
    root = Directory(p.join(temp.path, 'shop'))..createSync();
    sdkLog = File(p.join(temp.path, 'sdk.log'));
  });
  tearDown(() => temp.deleteSync(recursive: true));

  const unformatted = 'void  main( ){print( 1);}\n';
  const formatted = 'void main() {\n  print(1);\n}\n';

  void write(String path, String content) {
    File(p.join(root.path, path))
      ..parent.createSync(recursive: true)
      ..writeAsStringSync(content);
  }

  String read(String path) => File(p.join(root.path, path)).readAsStringSync();

  void git(List<String> args) {
    final result = Process.runSync('git', args, workingDirectory: root.path);
    expect(result.exitCode, 0, reason: '${result.stderr}');
  }

  /// A project on `master` with one unformatted file of every kind, then a
  /// branch that changes some of them and adds one it has not committed.
  void branchedProject({String pinned = '9.9.9', bool installed = true}) {
    for (final role in ['shop_shared', 'shop_server', 'shop_flutter']) {
      write('$role/pubspec.yaml', 'name: $role\nenvironment:\n  sdk: ^3.0.0\n');
    }
    write('.gitignore', '.fvm/\n');
    write('shop_flutter/.fvmrc', jsonEncode({'flutter': pinned}));
    if (installed) {
      _fakeFlutterSdk(
        Directory(p.join(root.path, 'shop_flutter', '.fvm', 'flutter_sdk')),
        pinned,
        sdkLog,
      );
    }
    write('shop_shared/lib/old.dart', unformatted);
    write('shop_server/lib/changed.dart', 'void main() {}\n');
    write('shop_shared/lib/src/profile.dw.dart', unformatted);
    write(
      'shop_server/lib/generated/dw_schema.dart',
      '// GENERATED BY dartway generate. DO NOT EDIT.\n$unformatted',
    );
    write(
      'shop_server/lib/src/migrations/m20260101_000000_initial.dart',
      'class M extends DwDatabaseMigration {}\n',
    );
    git(['init', '-q', '-b', 'master']);
    git(['config', 'user.email', 'test@example.com']);
    git(['config', 'user.name', 'test']);
    git(['add', '.']);
    git(['commit', '-q', '-m', 'base']);

    git(['switch', '-q', '-c', 'feature']);
    write('shop_server/lib/changed.dart', unformatted);
    write('shop_shared/lib/src/profile.dw.dart', '$unformatted// more\n');
    write(
      'shop_server/lib/src/migrations/m20260101_000000_initial.dart',
      'class  M extends DwDatabaseMigration {  }\n',
    );
    git(['add', '.']);
    git(['commit', '-q', '-m', 'feature']);
    write('shop_flutter/lib/fresh.dart', unformatted);
  }

  Future<ProcessResult> dartway(
    List<String> args, {
    Map<String, String>? environment,
  }) => runTestProcess(
    Platform.resolvedExecutable,
    ['--packages=$packages', cli, ...args],
    workingDirectory: root.path,
    environment: {
      // No FVM cache of the person running the tests is consulted.
      'HOME': temp.path,
      'FVM_CACHE_PATH': p.join(temp.path, 'fvm'),
      ...?environment,
    },
  );

  test('formats only the files changed against the base branch, the '
      'untracked ones included, with the pinned Dart', () async {
    branchedProject();
    final result = await dartway(['format']);
    expect(result.exitCode, 0, reason: '${result.stdout}${result.stderr}');
    expect(
      result.stdout,
      allOf(
        contains('Formatting 2 Dart files of the files changed against master'),
        contains('the Dart of Flutter 9.9.9 (shop_flutter/.fvm/flutter_sdk)'),
      ),
    );
    expect(read('shop_server/lib/changed.dart'), formatted);
    expect(read('shop_flutter/lib/fresh.dart'), formatted);
    // Untouched by the branch: left as it is.
    expect(read('shop_shared/lib/old.dart'), unformatted);
    // Generated, and sealed: never handed to the formatter.
    expect(
      read('shop_shared/lib/src/profile.dw.dart'),
      '$unformatted// more\n',
    );
    expect(
      read('shop_server/lib/src/migrations/m20260101_000000_initial.dart'),
      'class  M extends DwDatabaseMigration {  }\n',
    );
    // The formatter that ran is the pinned SDK's, and it was handed exactly
    // the two files.
    final calls = sdkLog.readAsLinesSync();
    expect(calls, hasLength(1));
    expect(
      calls.single,
      'format shop_flutter/lib/fresh.dart shop_server/lib/changed.dart',
    );
  }, skip: Platform.isWindows ? 'the fake SDK is a shell script' : null);

  test(
    '--check writes nothing, lists the unformatted files and fails',
    () async {
      branchedProject();
      final result = await dartway(['format', '--check']);
      expect(result.exitCode, 1, reason: '${result.stdout}${result.stderr}');
      expect(
        result.stderr,
        allOf(
          contains('  shop_server/lib/changed.dart'),
          contains('  shop_flutter/lib/fresh.dart'),
          isNot(contains('old.dart')),
          contains('Run `dartway format`.'),
        ),
      );
      expect(read('shop_server/lib/changed.dart'), unformatted);

      await dartway(['format']);
      final clean = await dartway(['format', '--check']);
      expect(clean.exitCode, 0, reason: '${clean.stdout}${clean.stderr}');
    },
    skip: Platform.isWindows ? 'the fake SDK is a shell script' : null,
  );

  test('--all takes every file of the project but the generated ones and '
      'the migrations', () async {
    branchedProject();
    final result = await dartway(['format', '--all', '--check']);
    expect(result.exitCode, 1);
    expect(
      result.stderr,
      allOf(
        contains('shop_shared/lib/old.dart'),
        contains('shop_server/lib/changed.dart'),
        contains('shop_flutter/lib/fresh.dart'),
        isNot(contains('profile.dw.dart')),
        isNot(contains('dw_schema.dart')),
        isNot(contains('m20260101_000000_initial.dart')),
        contains('Run `dartway format --all`.'),
      ),
    );
  }, skip: Platform.isWindows ? 'the fake SDK is a shell script' : null);

  test('--base names the ref to compare against', () async {
    branchedProject();
    git(['add', '.']);
    git(['commit', '-q', '-m', 'fresh']);
    final result = await dartway(['format', '--check', '--base', 'HEAD~1']);
    expect(result.exitCode, 1);
    expect(result.stderr, contains('shop_flutter/lib/fresh.dart'));
    expect(result.stderr, isNot(contains('changed.dart')));
  }, skip: Platform.isWindows ? 'the fake SDK is a shell script' : null);

  test('refuses when the pinned Flutter is not installed, rather than '
      'format with another Dart', () async {
    branchedProject(pinned: '0.0.1', installed: false);
    final result = await dartway(
      ['format'],
      environment: {'PATH': '/usr/bin:/bin'},
    );
    expect(result.exitCode, 1);
    expect(
      result.stderr,
      allOf(
        contains('.fvmrc pins Flutter 0.0.1'),
        contains('fvm install 0.0.1'),
      ),
    );
    expect(read('shop_server/lib/changed.dart'), unformatted);
  });
}

/// A Flutter SDK of [version] at [sdk] whose `bin/dart` notes every call in
/// [log] and runs the Dart running this test.
void _fakeFlutterSdk(Directory sdk, String version, File log) {
  Directory(p.join(sdk.path, 'bin', 'cache')).createSync(recursive: true);
  File(
    p.join(sdk.path, 'bin', 'cache', 'flutter.version.json'),
  ).writeAsStringSync(jsonEncode({'frameworkVersion': version}));
  final dart = File(p.join(sdk.path, 'bin', 'dart'))
    ..writeAsStringSync(
      '#!/bin/sh\n'
      'echo "\$*" >> "${log.path}"\n'
      'exec "${Platform.resolvedExecutable}" "\$@"\n',
    );
  Process.runSync('chmod', ['+x', dart.path]);
}
